package com.lunar.genshin;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;
public class ReminderReceiver extends BroadcastReceiver {public static final String CHANNEL="lunar_dailies";public void onReceive(Context c,Intent i){if(c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;Intent o=new Intent(c,MainActivity.class);PendingIntent p=PendingIntent.getActivity(c,0,o,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL).setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("L.U.N.A.R. • Dailies").setContentText("Commissions, resin, expeditions and Crystal Cores.").setContentIntent(p).setAutoCancel(true).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(4107,n);}}
